head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.clickBzProcsNo = "";
/************************************************************************************
 * ID           :	ULDSTF05005
 * File           :	ULDSTF05005.xml
 * Name         :	신규상장
 * Author       :	yooYoungSup
 * Description  :	신규상장
 * Create Date  :	2026-08-03
 ************************************************************************************/

scwin.market = $c.session.getUserInfo("market");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — listSync 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.date.compareFromToDate(ica_SDate, ica_EDate, ["상장 일기간 시작일자", "상장 일기간 종료일자"], "yyyyMMdd");
        const toDay = $c.date.getServerDateTime();

        ica_SDate.setValue('19000101');
        ica_EDate.setValue($c.date.addDate(toDay, 60));

        if (scwin.market === "1" || scwin.market === "2" || scwin.market === "6") {
            grd_list.setColumnVisible("trMktNm", false);
            grd_list.setColumnVisible("fssUnqNoDupYn", false);
            rdo_SPOT_ISU_TRD_MKT_TP_CD.setValue(scwin.market)
            grp_mkt_gubun.hide();
        } else {
            grp_mkt_gubun.show();
        }
        if (scwin.market === "6") {
            // var usrCBData = "'ST^주권";
            // sbx_NEW_SECUGRP_ID.CBData = usrCBData; //사용자CBData 지정
            sbx_NEW_SECUGRP_ID.setValue("ST");
        }
        scwin.listSync();

        // 해당 그룹 안의 컴포넌트에서 엔터키가 발생하면 해당 컴포넌트의 값을 DataCollection에 저장하고 objFunc 함수를 실행한다.
        $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05005.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 조회버튼클릭 — 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05005.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function(e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05005.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function(e) {
    try {
        if (sbx_NEW_SECUGRP_ID.getValue() === "") {
            $c.win.alert("신규등록할 [유가증권]을 선택하세요.");
            sbx_NEW_SECUGRP_ID.focus();
            return;
        } else {
            scwin.openDetail();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05005.btn_New_onclick" });
    }
};

/**
 * @method
 * @name img_CoSearch_onclick
 * @description 조회조건 팝업
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_CoSearch_onclick = async function(e) {
    try {
        const res = await $c.lc.popFindExamCorp(rdo_SECUGRP_ID.getValue());

        ibx_ISUR_CD.setValue(res.isurCd);
        ibx_COM_NM.setValue(res.comNm);

        if(res.isurCd !=="") {
        scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05005.img_CoSearch_onclick" });
    }
};

/**
 * @method
 * @name sbx_PeriodTp_onviewchange
 * @description 기간선택
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_PeriodTp_onviewchange = function (info) {
    try {
        let selVal = info.newValue;

        if($c.util.isEmpty(selVal)) {
            ica_SDate.setValue("");
            ica_EDate.setValue("");
        } else {
            $c.stf.setFromToDate(selVal, ica_SDate, ica_EDate);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05005.sbx_PeriodTp_onviewchange" });
    }
};

/**
 * @method
 * @name grd_IssRecv_oncelldblclick
 * @description 더블클릭(상세조회)
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IssRecv_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.openDetail(rowIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05005.grd_IssRecv_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {

    const chkValidate = await scwin.checkForm();

    if(!chkValidate) return;

    dma_searchReq.set("secugrpId", rdo_SECUGRP_ID.getValue());
    dma_searchReq.set("isurCd",ibx_ISUR_CD.getValue());
    dma_searchReq.set("spotIsuTrdMktTpCd",rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue());
    dma_searchReq.set("strDate",ica_SDate.getValue());
    dma_searchReq.set("string",ica_EDate.getValue());

    const sbmOptions = {
        id : "sbm_newlisting",
        action : "/api/listing/lstproc/stock/newlisting/select-list",
        method : "get",
        ref : "dma_searchReq",
        target : "dlt_newlistingRes=body",
        gridview : "grd_List",
        isProcessMsg : true
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        spa_page.setValue(dlt_newlistingRes.getRowCount());
    }

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getPar
 * @description 부모 화면(팝업 호출원)으로 돌려줄 파라미터 배열을 만든다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = getObjectValue(ibx_ISUR_CD); // 코드값을 포함할 컨트롤

    arrPar[1] = getObjectValue(ibx_COM_NM); // 명칭값을 포함할 컨트롤

    arrPar[2] = getObjectValue(rdo_SECUGRP_ID);

    arrPar[3] = getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD);
    arrPar[4] = SEARCH_TYP_SLR;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description 팝업이 돌려준 파라미터 배열을 화면 입력값에 반영한다.
 * @param {Array} arrPar 파라미터 배열
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    ibx_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    ibx_COM_NM.setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name setBzProcsNo
 * @description 업무처리번호를 화면 상태값에 설정한다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(row) {
    scwin.clickBzProcsNo = dlt_newlistingRes.getCellData(row, "bzProcsNo");
};

/**
 * @method
 * @name getBzProcsNo
 * @description 현재 업무처리번호를 반환한다.
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @func
 * @name fn_CheckForm
 * @description :조회 validation
 * @returns {void}
 * @hidden N
 */
scwin.checkForm = async function () {
        // $c.date.compareFromToDate(ica_SDate, ica_EDate, ["조회 시작일자", "조회 종료일자"], "yyyy-MM-dd");
        // if($c.date.compareFromToDate(ica_SDate, ica_EDate, ["조회 시작일자", "조회 종료일자"], "yyyy-MM-dd"));
        const options = {
                validateType : "alert",
                checkType : "single",
                focus : true,
                fields : {
                    rdo_SECUGRP_ID : {required : true, name : "증권구분"},
                    rdo_SPOT_ISU_TRD_MKT_TP_CD : { required : true, name : "시장구분코드" },
                    ica_SDate : { required : true, name : "상장일기간(시작일자)"   },
                    ica_EDate : { required : true, name : "상장일기간(종료일자)"   },
                }
        };

        const result = await $c.validate.validateDataCollect(panel_Top, options);
        if (!result) {
            return false;
        }

        return result;
}

/**
 * @method
 * @name excelDown
 * @description 함수명 : fn_ExcelDown() 설명 : 정보를 excel로 다운 받는다
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (grd_list.getRowCount() <= 0) {
        $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_list, {fileName: "신규상장", type: "8"});
};

/**
 * @method
 * @name openDetail
 * @description 팝업호출
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function(row) {
    let secugrpId;
    let pageId;

    if (row >= 0) {
        // 그리드에서 선택시
        scwin.setBzProcsNo(row);
        secugrpId = dlt_newlistingRes.getCellData(row, 'secugrpId');
    } else {
        // 신규버튼 선택시
        scwin.clickBzProcsNo = ""; // 초기화
        secugrpId = sbx_NEW_SECUGRP_ID.getValue();
    }
    // console.log(":::::::::::::: "+ $c.lc.getGlbValue("SECUGRP_ID_ST"));
    // if (secugrpId == $c.lc.getGlbValue("SECUGRP_ID_ST")) { // as-is왜 화면 2개로?
        pageId = "ULDSTF05006";
    // } else if (secugrpId ==  $c.lc.getGlbValue("SECUGRP_ID_DR") || secugrpId == $c.lc.getGlbValue("SECUGRP_ID_FS")) {
    //   pageId = "ULDSTF05007";
    // }
    const url = "/ui/lst/lstproc/"+pageId+".xml";

    const opts = {
        id: pageId,
        popupName: $c.lc.getSecuGrpNm(secugrpId)+" 신규상장관리",
        width: 1600,
        height: 1800,
        frameModal: "top",
    };

    const popData = dlt_newlistingRes.getRowJSON(row);

    $c.win.openPopup(url, opts, popData);

    // frame.CreateDialogFrame("STOCK_LISTING", "/lstproc/" + pageId + ".xml", fn_getSecuGrpNm(secugrpId) + " 신규상장관리", 220, 0, 1020, hight, "window");
};
